package com.marketintel.service;
import com.marketintel.model.*;import com.marketintel.repository.HistoricalFeatureRepository;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class WalkForwardMlServiceTest {@Test void producesMultipleFutureOnlyFolds(){var repo=mock(HistoricalFeatureRepository.class);var data=new ArrayList<HistoricalFeature>();for(int i=0;i<80;i++){double close=100+i+(i%2==0?1:0);data.add(new HistoricalFeature("TEST",Instant.parse("2026-01-01T00:00:00Z").plusSeconds(i*86400),close,close,close,close,100,.01,close-2,close-3,close-1,55,2,1));}when(repo.findBySymbolAndTimestampBetweenOrderByTimestampAsc(eq("TEST"),any(),any())).thenReturn(data);var store=new FeatureStoreService(null,repo);var result=new WalkForwardMlService(store).validate("TEST",new WalkForwardRequest("TEST",30,10,10,4,.01,10));assertEquals(4,result.folds().size());assertEquals(36,result.totalTestSamples());}}
